files.content:
// Block (composition) — a social feed post: author header + text + optional media
// + like/comment/share actions. Contract: docs/rules/block-contract.md. Composes
// Card (surface), Avatar, and Button (actions); owns only layout; mints no tokens.
// Distinct from BlogPostGrid (article cards).
import type { ReactNode, Ref } from "react";
import { Text } from "react-aria-components";
import { Comment, Heart, Share } from "../components/icons";
import { Avatar } from "../components/Avatar";
import { Media } from "../components/Media";
import { Button } from "../components/Button";
import { Card } from "../components/Card";
import "./PostCard.css";

export interface PostCardAuthor {
  /** Display name. */
  name: string;
  /** Optional @handle shown under the name. */
  handle?: string;
  /** Optional avatar image URL. */
  avatarSrc?: string;
}

export interface PostCardProps {
  /** Post author. */
  author: PostCardAuthor;
  /** Relative or absolute time label. */
  timestamp?: string;
  /** Post body content. */
  content?: ReactNode;
  /** Optional attached image. */
  image?: { src: string; alt: string };
  /** Like count shown next to the like action. */
  likeCount?: number;
  /** Comment count shown next to the comment action. */
  commentCount?: number;
  onLike?: () => void;
  onComment?: () => void;
  onShare?: () => void;
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

// The Avatar's fallback: `Avatar` derives nothing from `alt`, so an avatar with no `src` and no
// children renders an empty circle. Same helper as its peers (`ProfileCard`, `ReviewList`,
// `TeamGrid`), duplicated per Block on purpose — §7 copy-friendly.
function initials(name: string) {
  return name
    .split(" ")
    .map((part) => part[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();
}

export function PostCard({
  author,
  timestamp,
  content,
  image,
  likeCount,
  commentCount,
  onLike,
  onComment,
  onShare,
  className,
  ref,
}: PostCardProps) {
  return (
    <Card ref={ref} className={className ? `sd-postcard ${className}` : "sd-postcard"}>
      <div className="sd-postcard__header">
        <Avatar src={author.avatarSrc} alt={author.name} size="small">
          {initials(author.name)}
        </Avatar>
        <div className="sd-postcard__author">
          <span className="sd-postcard__name sd-type-body-medium">{author.name}</span>
          {author.handle && (
            <span className="sd-postcard__handle sd-type-caption-medium">{author.handle}</span>
          )}
        </div>
        {timestamp && (
          <div className="sd-postcard__meta">
            <time className="sd-postcard__timestamp sd-type-caption-medium">{timestamp}</time>
          </div>
        )}
      </div>

      {content && (
        <>
          <div className="sd-postcard__content sd-type-body-medium">{content}</div>
        </>
      )}

      {image && (
        <Media className="sd-postcard__media">
          <img className="sd-postcard__media-image" src={image.src} alt={image.alt} />
        </Media>
      )}

      {/* usage: chrome — the post's reaction bar */}
      <div className="sd-postcard__actions">
        <Button variant="ghost" size="small" onPress={onLike} aria-label="Like">
          <Heart aria-hidden size="1em" />
          <Text className="sd-postcard__count">{likeCount ?? 0}</Text>
        </Button>
        <Button variant="ghost" size="small" onPress={onComment} aria-label="Comment">
          <Comment aria-hidden size="1em" />
          <Text className="sd-postcard__count">{commentCount ?? 0}</Text>
        </Button>
        <Button variant="ghost" size="small" isIconOnly onPress={onShare} aria-label="Share">
          <Share aria-hidden size="1em" />
        </Button>
      </div>
    </Card>
  );
}

/* PostCard.css — .sd-postcard (Block)
   Arrangement only: Card owns the surface; this Block places the author header,
   body, media, and action row. The media image fills the card width; actions sit
   in a row. No look (color/border/radius), no tokens. */
.sd-postcard__header {
  display: flex;
  align-items: center;
  gap: var(--sd-space-small);
}

.sd-postcard__author {
  display: flex;
  flex-direction: column;
  /* The name↔handle pair IS this container's whole content, which `token-contract.md`
     § Choosing a Sys rung answers with `2x-small` — `grid-list.item.content.gap` is the reference
     for the same pair inside a rich row. Without it the pair runs on the two line-heights alone, 0 as
     a box and 3.5px as ink, which `heading-pair:check` cannot see because it judges structure. */
  gap: var(--sd-space-2x-small);
  min-width: 0;
}

/* The Indent around the timestamp is the row's last flex item, so it carries the push to the end. */
.sd-postcard__meta {
  margin-inline-start: auto;
  flex: 0 0 auto;
  color: var(--sd-color-text-muted);
}

.sd-postcard__media-image {
  display: block;
  width: 100%;
  height: auto;
}

.sd-postcard__actions {
  display: flex;
  align-items: center;
  gap: var(--sd-space-x-small);
}

.sd-postcard__handle {
  color: var(--sd-color-text-muted);
}
